# Problem: minimum edit distance (Levenshtein) between two strings.
# DP on prefix pairs. dp[i][j] = edit distance between a[:i] and b[:j].
# Three choices per cell: insert, delete, or replace (or skip on match).
def edit_distance(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    # Base row/column: empty prefix needs i or j edits.
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]  # match: no edit needed
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
    return dp[m][n]
```

