# Problem: merge any overlapping intervals.
# Sort by start; sweep; extend the last merged interval if it overlaps, else start a new one.
def merge_intervals(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [list(intervals[0])]
    for start, end in intervals[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)  # extend
        else:
            merged.append([start, end])  # disjoint
    return merged
```

