# Problem: group integers by their remainder mod k.
# Walk; use the remainder as the dict key; append.
def group_by_remainder(nums, k):
    if k <= 0:
        return {}
    groups = {}
    for n in nums:
        r = n % k
        groups.setdefault(r, []).append(n)
    return groups
```

