# Problem: leftmost insertion point for target in sorted array.
# Binary search for first index i where arr[i] >= target.
def lower_bound(arr, target):
    lo, hi = 0, len(arr)
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] < target:
            lo = mid + 1  # insertion point is after mid
        else:
            hi = mid  # insertion point is at or before mid
    return lo
