# Problem: tree height (max depth from root to any leaf).
# Recursive: depth(node) = 1 + max(depth(left), depth(right)); empty tree depth = 0.
def max_depth(root):
    if not root:
        return 0
    return 1 + max(max_depth(root.left), max_depth(root.right))
