# Problem: count grid paths moving only right or down.
# DP: dp[i][j] = dp[i-1][j] + dp[i][j-1]. First row/col are all 1 (only one path each).
def unique_paths(m, n):
    dp = [[1] * n for _ in range(m)]
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]
    return dp[m-1][n-1]
